// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadOutfit = makeLoadFont('Outfit');

// Initialize fonts at module level
const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: outfitFamily } = loadOutfit();

// Font mapping for dynamic selection
const fontMap = {
  Inter: interFamily,
  "Space Grotesk": spaceGroteskFamily,
  Outfit: outfitFamily,
} as const;



export type RainbowHelloWorldProps = Record<string, any>;

const RAINBOW_COLORS = [
  "#FF3B30", // Red
  "#FF9500", // Orange
  "#FFCC00", // Yellow
  "#34C759", // Green
  "#5AC8FA", // Cyan
  "#007AFF", // Blue
  "#5856D6", // Purple
  "#FF2D55", // Pink
];

// Reusable 4-pointed sparkle star path
const STAR_PATH = "M 12 0 Q 12 12 24 12 Q 12 12 12 24 Q 12 12 0 12 Q 12 12 12 0";

const RainbowHelloWorld: React.FC<RainbowHelloWorldProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 4,
  text = "Hello World",
  textFontFamily = "Space Grotesk",
  lineThickness = 8,
  lineSpacing = 16,
  glowIntensity = 6,
  starCount = 40,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const selectedFont = fontMap[textFontFamily as keyof typeof fontMap] || interFamily;

  // --- Geometry Calculations for the Track ---
  // The track comes from the right, curves left (180deg), goes right, curves down (90deg).
  
  const centerY = height * 0.45;
  const outerRadius = height * 0.28; // Radius of the outermost (Red) line on the left turn
  const curve1CenterX = width * 0.22;
  const curve2CenterX = width * 0.78;
  const baseR2 = height * 0.12; // Radius of the innermost (Red) line on the down turn

  // Pre-calculate path strings and estimated lengths for the 8 rainbow lines
  const paths = useMemo(() => {
    return RAINBOW_COLORS.map((color, i) => {
      // Top stretch and left curve (180 deg)
      const r1 = outerRadius - i * lineSpacing;
      const y1 = centerY - r1;
      const y2 = centerY + r1;
      
      // Right curve (90 deg down)
      // To keep centers concentric and track width constant, radius increases for outer lines
      const r2 = baseR2 + i * lineSpacing;
      
      const startX = width + 200; // Start offscreen right
      const endY = height + 200;   // End offscreen bottom

      // Build SVG Path
      const d = `
        M ${startX} ${y1}
        L ${curve1CenterX} ${y1}
        A ${r1} ${r1} 0 0 0 ${curve1CenterX} ${y2}
        L ${curve2CenterX} ${y2}
        A ${r2} ${r2} 0 0 1 ${curve2CenterX + r2} ${y2 + r2}
        L ${curve2CenterX + r2} ${endY}
      `;

      // Mathematically estimate path length to avoid needing complex DOM measurements
      const l1 = startX - curve1CenterX;
      const a1 = Math.PI * r1; // Half circle
      const l2 = curve2CenterX - curve1CenterX;
      const a2 = (Math.PI * r2) / 2; // Quarter circle
      const l3 = endY - (y2 + r2);
      const totalLength = l1 + a1 + l2 + a2 + l3;

      return { d, color, totalLength };
    });
  }, [width, height, lineSpacing, outerRadius, curve1CenterX, curve2CenterX, baseR2, centerY]);

  // --- Star Generation ---
  const stars = useMemo(() => {
    return Array.from({ length: starCount }).map((_, i) => ({
      id: i,
      x: random(`star-x-${i}`) * width,
      y: random(`star-y-${i}`) * height,
      size: 0.3 + random(`star-size-${i}`) * 0.7,
      color: RAINBOW_COLORS[Math.floor(random(`star-color-${i}`) * RAINBOW_COLORS.length)],
      delay: random(`star-delay-${i}`) * 100,
      speed: 0.03 + random(`star-speed-${i}`) * 0.05,
    }));
  }, [starCount, width, height]);

  // --- Animations ---
  
  // Text Entrance
  const textScale = spring({
    frame: frame - 50,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  
  const textOpacity = interpolate(frame, [45, 65], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Stars */}
      <AbsoluteFill>
        {stars.map((star) => {
          // Continuous deterministic twinkling based on frame
          const twinkle = Math.pow(Math.sin((frame + star.delay) * star.speed), 2);
          const opacity = 0.1 + twinkle * 0.9;
          const scale = 0.8 + twinkle * 0.4;
          
          return (
            <div
              key={star.id}
              style={{
                position: "absolute",
                left: star.x,
                top: star.y,
                width: 24,
                height: 24,
                transform: `translate(-50%, -50%) scale(${star.size * scale})`,
                opacity: opacity,
                color: star.color,
                transition: "none",
              }}
            >
              <svg viewBox="0 0 24 24" style={{ width: "100%", height: "100%", filter: `drop-shadow(0px 0px 2px ${star.color})` }}>
                <path d={STAR_PATH} fill="currentColor" />
              </svg>
            </div>
          );
        })}
      </AbsoluteFill>

      {/* Rainbow Track */}
      <AbsoluteFill>
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ overflow: "visible" }}>
          {paths.map((path, i) => {
            // Stagger the drawing of each line
            const staggerDelay = i * 4;
            
            // Draw in from right to left
            const drawProgress = interpolate(
              frame - staggerDelay,
              [0, 90], // Duration of drawing
              [path.totalLength, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.bezier(0.25, 1, 0.5, 1),
              }
            );

            return (
              <path
                key={`line-${i}`}
                d={path.d}
                fill="none"
                stroke={path.color}
                strokeWidth={lineThickness}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray={path.totalLength}
                strokeDashoffset={drawProgress}
                style={{
                  filter: glowIntensity > 0 ? `drop-shadow(0px 0px ${glowIntensity}px ${path.color}80)` : 'none',
                  transition: "none",
                }}
              />
            );
          })}
        </svg>
      </AbsoluteFill>

      {/* Main Text */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transform: `translateY(-${height * 0.01}px)`, // Slight optical adjustment to center perfectly in the track gap
        }}
      >
        <div
          style={{
            fontFamily: selectedFont,
            fontSize: height * 0.16,
            fontWeight: 700,
            letterSpacing: "-0.02em",
            opacity: textOpacity,
            transform: `scale(${interpolate(textScale, [0, 1], [0.8, 1])})`,
            // Apply perfect rainbow gradient to text
            backgroundImage: `linear-gradient(90deg, ${RAINBOW_COLORS.join(", ")})`,
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            color: "transparent", // Fallback
            whiteSpace: "nowrap",
            // Subtle glow for the text itself
            filter: `drop-shadow(0px 4px 24px rgba(255,255,255,0.15))`,
            transition: "none",
          }}
        >
          {text}
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default RainbowHelloWorld;